using OcctSharp.DocumentProjections;
namespace OcctSharp.Tests.Shared;
internal static class BatchBICollectionWorkflow {
 internal static readonly Guid Custom=Guid.Parse("72e8f0f6-f9dd-4498-aad1-b23d534a8c00");
 internal static void Fill(DocumentProjectionContext context,DocumentProjectionLabel label,DocumentProjectionLabel target){context.ReplaceCollections([
  new(label,DirectCollectionKind.IntegerArray,DirectCollections.Array<int>(-7,[0,9,-2])),
  new(label,DirectCollectionKind.RealArray,DirectCollections.Array<double>(8,[0.0,.5,-2])),
  new(label,DirectCollectionKind.StringArray,DirectCollections.Array<string>(-3,["","数组🙂","汉字"])),
  new(label,DirectCollectionKind.ByteArray,DirectCollections.Array<byte>(3,[0,255,7])),
  new(label,DirectCollectionKind.BooleanArray,DirectCollections.Array<bool>(-2,[true,false,true,false,false,true,false,true,true])),
  new(label,DirectCollectionKind.ReferenceArray,DirectCollections.Array<DocumentProjectionLabel?>(-5,[target,null,target])),
  new(label,DirectCollectionKind.IntegerList,DirectCollections.List<int>([1,0,1])),
  new(label,DirectCollectionKind.RealList,DirectCollections.List<double>([0.0,.5,.5])),
  new(label,DirectCollectionKind.StringList,DirectCollections.List<string>(["","序列🙂","重复","重复"])),
  new(label,DirectCollectionKind.IntegerArray,DirectCollections.Array<int>(11,[42]),Custom)]);}
 internal static DirectCollection<T> Read<T>(DocumentProjectionContext context,DocumentProjectionLabel label,DirectCollectionKind kind,Guid? id=null)=>context.ReadCollection(label,kind,id)?.Value as DirectCollection<T>??throw new InvalidOperationException("BI missing/wrong direct attribute type.");
 internal static void Verify(DocumentProjectionContext context,DocumentProjectionLabel label,string target){
  var integers=Read<int>(context,label,DirectCollectionKind.IntegerArray);if(integers.LowerBound!=-7||!integers.Values.SequenceEqual([0,9,-2]))throw new InvalidOperationException("BI integer bounds/content failed.");
  if(!Read<double>(context,label,DirectCollectionKind.RealArray).Values.SequenceEqual([0,.5,-2])||!Read<string>(context,label,DirectCollectionKind.StringArray).Values.SequenceEqual(["","数组🙂","汉字"])||!Read<byte>(context,label,DirectCollectionKind.ByteArray).Values.SequenceEqual(new byte[]{0,255,7})||!Read<bool>(context,label,DirectCollectionKind.BooleanArray).Values.SequenceEqual([true,false,true,false,false,true,false,true,true]))throw new InvalidOperationException("BI typed direct array content failed.");
  var refs=Read<DocumentProjectionLabel?>(context,label,DirectCollectionKind.ReferenceArray);if(refs.LowerBound!=-5||refs.Values.Count!=3||refs.Values[0]?.Entry!=target||refs.Values[1] is not null||refs.Values[2]?.Entry!=target||refs.Values[0]?.ContextIdentity!=context.Identity)throw new InvalidOperationException("BI exact context reference/null-slot ordinals failed.");
  if(!Read<int>(context,label,DirectCollectionKind.IntegerList).Values.SequenceEqual([1,0,1])||!Read<double>(context,label,DirectCollectionKind.RealList).Values.SequenceEqual([0,.5,.5])||!Read<string>(context,label,DirectCollectionKind.StringList).Values.SequenceEqual(["","序列🙂","重复","重复"])||Read<int>(context,label,DirectCollectionKind.IntegerArray,Custom).Values.Single()!=42)throw new InvalidOperationException("BI direct list/GUID content failed.");
  if(context.Snapshot(label).NamedData is not null)throw new InvalidOperationException("BI direct attributes were substituted with NamedData.");
 }
 internal static void RunNative(){using var document=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(document);var main=context.GetLabel("0:1");var root=context.GetLabel("0:");if(context.ReadCollection(main,DirectCollectionKind.IntegerArray) is not null)throw new InvalidOperationException("BI missing read created an attribute.");document.NewCommand();Fill(context,main,root);if(!document.CommitCommand())throw new InvalidOperationException("BI command commit failed.");try{Verify(context,main,root.Entry);}catch(Exception error){throw new InvalidOperationException("BI initial verification",error);}var detached=Read<string>(context,main,DirectCollectionKind.StringArray);if(!document.Undo()||context.ReadCollection(main,DirectCollectionKind.IntegerArray) is not null||!document.Redo())throw new InvalidOperationException("BI undo/redo failed.");try{Verify(context,main,root.Entry);}catch(Exception error){throw new InvalidOperationException("BI redo verification",error);}document.NewCommand();context.RemoveCollection(main,DirectCollectionKind.IntegerArray);document.AbortCommand();try{Verify(context,main,root.Entry);}catch(Exception error){throw new InvalidOperationException("BI abort verification",error);}document.Dispose();if(detached.Values[1]!="数组🙂")throw new InvalidOperationException("BI detached copy lifetime failed.");}
#if !DIRECT_MODULE_CONSUMER
 internal static void RunPersistent(){string directory=Path.Combine(Path.GetTempPath(),"OcctSharp.BI."+Guid.NewGuid());Directory.CreateDirectory(directory);try{using var document=XdeDocument.Create();using var box=ShapeFactory.CreateBox(2,3,4);string first,second,part;using(var command=document.BeginTransaction("BI direct repeated occurrence collections")){var definition=document.AddShape(box,"direct part");var assembly=document.AddAssembly("repeat");using var identity=TopLocLocation.Identity;var a=document.AddComponent(assembly,definition,identity);var b=document.AddComponent(assembly,definition,identity);part=definition.Entry;first=a.Entry;second=b.Entry;Fill(document.Projections,document.Projections.GetLabel(first),document.Projections.GetLabel(part));document.Projections.ReplaceCollection(document.Projections.GetLabel(second),DirectCollections.Array<int>(-2,[99]));if(!command.Commit())throw new InvalidOperationException("BI XCAF commit failed.");}foreach(var format in new[]{DocumentStorageFormat.BinXcaf,DocumentStorageFormat.XmlXcaf}){string path=Path.Combine(directory,format==DocumentStorageFormat.BinXcaf?"model.xbf":"model.xml");document.Save(path,format);if(format==DocumentStorageFormat.XmlXcaf)_=System.Xml.Linq.XDocument.Load(path);using var reopened=XdeDocument.Open(path);Verify(reopened.Projections,reopened.Projections.GetLabel(first),part);if(Read<int>(reopened.Projections,reopened.Projections.GetLabel(second),DirectCollectionKind.IntegerArray).Values.Single()!=99||reopened.Projections.ReadCollection(reopened.Projections.GetLabel(part),DirectCollectionKind.IntegerArray) is not null||reopened.GetLabel(first).ReferredShape.Entry!=part||reopened.GetLabel(second).ReferredShape.Entry!=part)throw new InvalidOperationException("BI repeated occurrence persistence/domain isolation failed.");}}finally{Directory.Delete(directory,true);}}
#endif
 internal static void Run(){RunNative();
#if !DIRECT_MODULE_CONSUMER
 RunPersistent();
#endif
 }
}
